import {WEAPON_SLOTS,SLOT_LABELS,attachment,weaponStats,previewBuild,effectLines,EQUIPMENT} from './loadout.js';
const paths=['M10 32h26v-5h37v5h25v9H72v10H59V40H42l-4 14H28l3-14H10z','M19 24h65v15H49l-5 23H29l4-27H19z','M13 29h22v-5h40v8h20v9H63v21H49V41H35l-2 13H20l3-15H13z','M5 31h30v-9h24v9h44v8H64v7H47l-4 13H29l3-20H5z','M9 24h82v7h9v20H11V40H6V29h3zm24 27h14v15H33z','M5 31h35v-6h64v8H76v9H49l-7 18H28l6-20H5z'];
export function gunIcon(g){return `<svg class="gun-icon" viewBox="0 0 110 75" aria-hidden="true"><path d="${paths[g]}" fill="currentColor"/></svg>`}
export function reticleIcon(type){return `<svg class="reticle-icon" viewBox="0 0 60 60" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.5">${type==='dot'?'<circle cx="30" cy="30" r="2" fill="currentColor"/>':type==='ring'?'<circle cx="30" cy="30" r="13"/><circle cx="30" cy="30" r="1.5" fill="currentColor"/>':type==='holo'?'<circle cx="30" cy="30" r="12"/><path d="M30 12v7m0 22v7M12 30h7m22 0h7"/><circle cx="30" cy="30" r="1"/>':type==='chevron'?'<path d="m23 34 7-8 7 8M30 37v7"/>':type==='duplex'?'<path d="M30 7v15m0 16v15M7 30h15m16 0h15" stroke-width="3"/><path d="M30 21v18M21 30h18" stroke-width=".7"/>':'<path d="M30 9v16m0 10v16M9 30h16m10 0h16"/><circle cx="30" cy="30" r="2"/>'}</svg>`}
function statsHTML(base,g,builds,preview,perks){const a=weaponStats(base,g,builds),b=weaponStats(base,g,preview),rows=[['DAMAGE',a.damage*(g===4?150/110:1),b.damage*(g===4?150/110:1),g===5?' / PELLET':'',true],['FIRE RATE',60/a.interval,60/b.interval,' RPM',true],['MAGAZINE',a.mag,b.mag,'',true],['RELOAD',a.reload*(perks.reload?.65:1),b.reload*(perks.reload?.65:1),' s',false],['RECOIL',a.recoil*100,b.recoil*100,'%',false],['AIM TIME',.22*a.ads*(perks.quickdraw?.8:1),.22*b.ads*(perks.quickdraw?.8:1),' s',false]];return rows.map(([name,x,y,unit,high])=>{const format=n=>name==='RELOAD'||name==='AIM TIME'?n.toFixed(2):Number.isInteger(n)?n:Math.round(n*10)/10,diff=Math.abs(x-y)>.001;return `<div class="weapon-stat"><small>${name}</small><strong>${format(x)}${diff?`<span class="stat-change ${(y>x)===high?'better':'worse'}"> → ${format(y)}</span>`:''}<em>${unit}</em></strong></div>`}).join('')}
export function loadoutHTML(s){const {weapons,owned,builds,credits,perks,equipment,round,gun,slot,candidate,tab,inspect,upgrades}=s,w=weapons[gun],has=owned.includes(gun),items=WEAPON_SLOTS[gun][slot]||[],selected=attachment(gun,candidate),current=builds[gun]?.slots[slot]||'',preview=previewBuild(builds,gun,slot,candidate),price=selected&&!builds[gun]?.owned.includes(candidate)?selected.price:0;
const arsenal=weapons.map((w,g)=>`<button class="arsenal-gun ${g===gun?'selected':''} ${owned.includes(g)?'owned':''}" data-gun="${g}" aria-pressed="${g===gun}">${gunIcon(g)}<span><b>${w.name}</b><small>${w.label}</small></span><em>${owned.includes(g)?'OWNED':(w.price||220)+' CR'}</em></button>`).join('');
const tabs=['weapons','perks','equipment'].map(t=>`<button data-tab="${t}" class="${tab===t?'active':''}" aria-pressed="${tab===t}">${t.toUpperCase()}</button>`).join('');
const slots=Object.entries(WEAPON_SLOTS[gun]).map(([key])=>{const a=attachment(gun,builds[gun]?.slots[key]);return `<button class="attachment-slot ${slot===key?'selected':''} ${a?'filled':''}" data-slot="${key}" aria-pressed="${slot===key}"><small>${SLOT_LABELS[key]}</small><b>${a?.name||'Standard'}</b><span>${a?'●':'+'}</span></button>`}).join('');
const options=[null,...items].map(a=>{const id=a?.id||'',fitted=current===id,bought=!a||builds[gun]?.owned.includes(id);return `<button class="attachment-option ${candidate===id?'selected':''}" data-part="${id}" aria-pressed="${candidate===id}">${a?.slot==='optic'?reticleIcon(a.reticle):'<span class="part-symbol">'+(!a?'—':a.visual==='long'?'━━':a.visual==='short'?'━':'▰')+'</span>'}<span><b>${a?.name||'Standard'}</b><small>${fitted?'FITTED':bought?'OWNED':a.price+' CR'}</small></span>${fitted?'<em>✓</em>':''}</button>`}).join('');
const lines=effectLines(selected).map(l=>`<li class="${l.good?'better':'worse'}">${l.text}</li>`).join('');
const weaponContent=`<aside class="arsenal"><div class="column-label">WEAPONS <span>${owned.length} / 6</span></div>${arsenal}</aside><section class="weapon-workbench"><div class="weapon-title"><div><small>${w.label.toUpperCase()}</small><h2>${w.name}</h2></div>${has?`<button class="starting-weapon ${s.starting===gun?'is-starting':''}" id="starting-weapon" ${inspect?'disabled':''}>${s.starting===gun?'✓ STARTING WEAPON':'SET STARTING WEAPON'}</button>`:'<span class="weapon-unowned">NOT OWNED</span>'}</div><div id="weapon-preview" class="weapon-preview"><span class="bench-index">${String(gun+1).padStart(2,'0')} / 06</span><span class="bench-state">${candidate!==current?'ATTACHMENT PREVIEW':'CURRENT BUILD'}</span><div class="bench-fallback">${gunIcon(gun)}</div><div class="bench-caption">${selected?.slot==='optic'?selected.name:(gun===3?'Piercing rail shot':gun===4?'Splash damage · Rocket jumps':gun===5?'12 pellets · Tight core':weaponStats(w,gun,preview).mag+' rounds · Unlimited reserves')}</div><button id="rotate-weapon" class="rotate-weapon" aria-label="Rotate weapon">ROTATE ↻</button></div><div class="weapon-stats">${statsHTML(w,gun,builds,preview,perks)}</div><div class="slots-heading"><small>ATTACHMENTS</small><span>${Object.keys(builds[gun]?.slots||{}).length} / 5 FITTED</span></div><div class="attachment-slots">${slots}</div><div class="build-tools"><span>One part per slot. Owned parts swap free.</span><button id="reset-build" ${inspect||!has?'disabled':''}>RESET BUILD</button></div></section><aside class="parts-panel"><div class="column-label">${SLOT_LABELS[slot].toUpperCase()} <span>${items.length} OPTIONS</span></div><div class="attachment-options ${slot==='optic'?'optic-options':''}">${options}</div><div class="part-details"><small>${selected?.zoom?selected.zoom+'× OPTIC':'ATTACHMENT'}</small><h3>${selected?.name||'Standard'}</h3>${selected?.slot==='optic'?`<div class="optic-detail">${reticleIcon(selected.reticle)}<span>${selected.zoom}×<small>${selected.zoom===1?'Wide view':'Closer view'}</small></span></div>`:''}<ul>${lines||'<li>Original weapon handling.</li>'}</ul><button id="loadout-action" class="fit-button" ${inspect||!has||candidate===current||price>credits?'disabled':''}>${inspect?'AVAILABLE BETWEEN ROUNDS':!has?'BUY WEAPON FIRST':candidate===current?'FITTED':price>credits?'NEED '+(price-credits)+' CR':price?'BUY & FIT · '+price+' CR':'FIT ATTACHMENT'}</button>${!has&&!inspect?`<button id="buy-weapon" data-buy="gun${gun}" class="buy-weapon" ${credits<(w.price||220)?'disabled':''}>${credits<(w.price||220)?'NEED '+((w.price||220)-credits)+' CR':'BUY '+w.name+' · '+(w.price||220)+' CR'}</button>`:''}</div></aside>`;
const perkContent=`<section class="upgrade-deck"><div class="deck-heading"><h2>PERKS</h2><p>Permanent for this run. All owned perks stay active.</p></div><div class="perk-grid">${upgrades.filter(u=>u.gun===undefined&&u.category==='PERK').map((u,i)=>`<button class="perk-tile ${perks[u.id]?'purchased':''}" data-buy="${u.id}" ${inspect||perks[u.id]||credits<u.price?'disabled':''}><span class="perk-number">${String(i+1).padStart(2,'0')}</span><small>PERK</small><h3>${u.name}</h3><p>${u.desc}</p><b>${perks[u.id]?'✓ ACTIVE':credits<u.price?'NEED '+(u.price-credits)+' CR':u.price+' CR'}</b></button>`).join('')}</div></section>`;
const gearContent=`<section class="upgrade-deck"><div class="deck-heading"><h2>EQUIPMENT</h2><p>One throwable and one killstreak. Owned equipment swaps free.</p></div>${Object.entries(EQUIPMENT).map(([key,values])=>`<div class="gear-heading"><small>${key==='throwable'?'THROWABLE':'KILLSTREAK'}</small><span>${key==='throwable'?(perks.frags?4:2)+' PER MATCH':'F TO ACTIVATE · 3 KILLS WITHOUT DYING'}</span></div><div class="gear-grid">${values.map((item,i)=>{const fitted=equipment[key]===item.id,bought=equipment.owned.includes(item.id);return `<button class="gear-tile ${fitted?'purchased':''}" data-gear="${key}:${item.id}" ${inspect||fitted||!bought&&credits<item.price?'disabled':''}><span class="gear-symbol">${key==='throwable'?['◉','◆','◷'][i]:['↘','ϟ','⋙'][i]}</span><h3>${item.name}</h3><p>${item.desc}</p><b>${fitted?'✓ EQUIPPED':bought?'EQUIP':credits<item.price?'NEED '+(item.price-credits)+' CR':item.price+' CR · BUY & EQUIP'}</b></button>`}).join('')}</div>`).join('')}<button class="bandolier" data-buy="frags" ${inspect||perks.frags||credits<160?'disabled':''}><b>BANDOLIER</b><span>4 grenades per match.</span><strong>${perks.frags?'✓ ACTIVE':'160 CR'}</strong></button></section>`;
return `<div class="loadout-shell"><div class="loadout-header"><span class="loadout-brand">DH<span>◉</span></span><div><small>${inspect?'DEAD HEAT':`ROUND ${String(round+1).padStart(2,'0')} / PREPARATION`}</small><h1>${inspect?'ARSENAL':'LOADOUT'}</h1></div><div class="loadout-wallet"><small>CREDITS</small><strong>${credits}<em> CR</em></strong></div></div><nav class="loadout-tabs" aria-label="Loadout sections">${tabs}<span>${inspect?'BROWSE WEAPONS & EQUIPMENT':'PURCHASES LAST FOR THIS RUN'}</span></nav><div class="loadout-content ${tab==='weapons'?'weapon-layout':''}">${tab==='weapons'?weaponContent:tab==='perks'?perkContent:gearContent}</div><footer class="loadout-footer"><button id="savequit" class="loadout-back">${inspect?'← MAIN MENU':'SAVE & EXIT'}</button><span id="loadout-status" role="status">${s.message||(!inspect?'Saved automatically':'Buy weapons and parts between rounds.')}</span>${inspect?'':`<button id="nextmatch" class="deploy-button">START ROUND ${round+1}<span>↗</span></button>`}</footer></div>`;
}
